style.svg:
) — вмикає повний цикл годування:
         появу м'яса (#meat-group), розкриття пащі (#upper-jaw, #lower-jaw,
         #mouth-interior) та зникнення відкушеного шматка (#meat-bite-chunk).
       ========================================================================== */
    .state-eat #meat-group {
      opacity: 1;
    }
    .state-eat #mouth-interior {
      animation: mouthInteriorFade 3s ease-in-out infinite;
    }
    .state-eat #upper-jaw {
      animation: upperJawChomp 3s ease-in-out infinite;
    }
    .state-eat #lower-jaw {
      animation: lowerJawChomp 3s ease-in-out infinite;
    }
    .state-eat #meat-bite-chunk {
      animation: meatChunkBitten 3s linear infinite;
    }
    .state-eat #meat-group {
      animation: meatShakeOnBite 3s ease-in-out infinite;
    }

    @keyframes upperJawChomp {
      0%, 10%   { transform: rotate(0deg); }
      28%, 40%  { transform: rotate(-24deg) translateX(2px); } /* Широке відкриття верхньої щелепи */
      46%       { transform: rotate(2deg) translateX(4px); }   /* Різкий укус */
      54%, 62%  { transform: rotate(-6deg); }                  /* Жування 1 */
      68%, 76%  { transform: rotate(-1deg); }                  /* Жування 2 */
      82%, 90%  { transform: rotate(-5deg); }                  /* Жування 3 */
      96%, 100% { transform: rotate(0deg); }
    }

    @keyframes lowerJawChomp {
      0%, 10%   { transform: rotate(0deg); }
      28%, 40%  { transform: rotate(20deg) translateX(2px); }  /* Опускання нижньої щелепи */
      46%       { transform: rotate(-1deg) translateX(4px); }  /* Змикання пащі при укусі */
      54%, 62%  { transform: rotate(5deg); }                   /* Жування 1 */
      68%, 76%  { transform: rotate(0deg); }                   /* Жування 2 */
      82%, 90%  { transform: rotate(4deg); }                   /* Жування 3 */
      96%, 100% { transform: rotate(0deg); }
    }

    @keyframes mouthInteriorFade {
      0%, 14%   { opacity: 0; }
      24%, 44%  { opacity: 1; }
      48%, 100% { opacity: 0; }
    }

    @keyframes meatChunkBitten {
      0%, 44%   { opacity: 1; transform: scale(1); }
      46%, 92%  { opacity: 0; transform: scale(0); } /* Відкушений шматок зникає в пащі */
      98%, 100% { opacity: 1; transform: scale(1); } /* Відновлення шматка для повтору циклу */
    }

    @keyframes meatShakeOnBite {
      0%, 44%   { transform: translate(118px, 64px) rotate(0deg); }
      47%       { transform: translate(121px, 65px) rotate(8deg); } /* Віддача м'яса від укусу */
      53%, 100% { transform: translate(118px, 64px) rotate(0deg); }
    }

    /* ==========================================================================
       2. АНІМАЦІЯ ПОВЗАННЯ
       Класи, що змінюють стани анімації:
       - .state-crawl (на кореневому тегу ) — запускає почерговий рух
         діагональних пар лап (#near-front-leg + #far-back-leg та
         #far-front-leg + #near-back-leg) і погойдування тулуба (#croc-body-group).
       ========================================================================== */
    .state-crawl #near-front-leg,
    .state-crawl #far-back-leg {
      animation: crawlLegSwingA 0.9s ease-in-out infinite;
    }
    .state-crawl #far-front-leg,
    .state-crawl #near-back-leg {
      animation: crawlLegSwingB 0.9s ease-in-out infinite;
    }
    .state-crawl #croc-body-group {
      animation: crawlBodySway 0.9s ease-in-out infinite;
    }

    @keyframes crawlLegSwingA {
      0%, 100% { transform: rotate(-20deg) translateY(-1.5px); }
      50%      { transform: rotate(22deg) translateY(0.5px); }
    }
    @keyframes crawlLegSwingB {
      0%, 100% { transform: rotate(22deg) translateY(0.5px); }
      50%      { transform: rotate(-20deg) translateY(-1.5px); }
    }
    @keyframes crawlBodySway {
      0%, 100% { transform: translateY(0px) rotate(-0.8deg); }
      25%      { transform: translateY(-1.5px) rotate(0deg); }
      50%      { transform: translateY(0px) rotate(0.8deg); }
      75%      { transform: translateY(-1.5px) rotate(0deg); }
    }
